"""Standard-library decompression operations for the ouch-compatible CLI."""
from __future__ import annotations
import bz2, gzip, lzma, os, shutil, tarfile, zipfile
from pathlib import Path, PurePosixPath

_SINGLE = {'.gz': gzip.decompress, '.bz2': bz2.decompress, '.bz': bz2.decompress,
           '.xz': lzma.decompress, '.lzma': lzma.decompress}
_ALIASES = {'.tgz': '.tar.gz', '.tbz': '.tar.bz', '.tbz2': '.tar.bz2', '.txz': '.tar.xz', '.tlzma': '.tar.lzma'}

def _strip_name(name: str) -> tuple[str, str]:
    low = name.lower()
    for alias, expanded in _ALIASES.items():
        if low.endswith(alias):
            return name[:-len(alias)] + expanded[len(alias):], expanded
    for ext in ('.tar.gz','.tar.bz2','.tar.bz','.tar.xz','.tar.lzma','.tar'):
        if low.endswith(ext): return name[:-len(ext)], ext
    return os.path.splitext(name)[0], os.path.splitext(name)[1].lower()

def _safe_join(root: Path, member: str) -> Path:
    # Archive member paths are interpreted relative to destination, never outside it.
    clean = PurePosixPath(member.replace('\\', '/'))
    parts = [p for p in clean.parts if p not in ('/', '..', '.')]
    return root.joinpath(*parts)

def _extract_tar(tf: tarfile.TarFile, root: Path) -> list[tuple[str,int]]:
    items=[]
    for m in tf.getmembers():
        dest=_safe_join(root,m.name)
        if m.isdir():
            dest.mkdir(parents=True,exist_ok=True)
        elif m.isfile():
            dest.parent.mkdir(parents=True,exist_ok=True)
            src=tf.extractfile(m)
            if src:
                with src, open(dest,'wb') as out: shutil.copyfileobj(src,out)
            try: os.chmod(dest,m.mode & 0o777)
            except OSError: pass
            items.append((str(dest),m.size))
        elif m.issym():
            dest.parent.mkdir(parents=True,exist_ok=True)
            try: os.symlink(m.linkname,dest)
            except OSError: pass
    return items

def _extract_zip(zf: zipfile.ZipFile, root: Path) -> list[tuple[str,int]]:
    items=[]
    for m in zf.infolist():
        dest=_safe_join(root,m.filename)
        if m.is_dir(): dest.mkdir(parents=True,exist_ok=True); continue
        dest.parent.mkdir(parents=True,exist_ok=True)
        with zf.open(m) as src, open(dest,'wb') as out: shutil.copyfileobj(src,out)
        items.append((str(dest),m.file_size))
    return items

def decompress_one(filename: str, output_dir: str|None=None, here: bool=False) -> tuple[str,list[tuple[str,int]]]:
    src=Path(filename)
    data=src.read_bytes()
    base, ext=_strip_name(src.name)
    is_tar = ext.startswith('.tar') or tarfile.is_tarfile(src)
    if ext == '.zip' or zipfile.is_zipfile(src):
        root=Path(output_dir) if output_dir is not None else (Path('.') if here else Path(base))
        root.mkdir(parents=True,exist_ok=True)
        with zipfile.ZipFile(src) as zf: entries=_extract_zip(zf,root)
        return str(root),entries
    if is_tar:
        root=Path(output_dir) if output_dir is not None else (Path('.') if here else Path(base))
        root.mkdir(parents=True,exist_ok=True)
        with tarfile.open(src,'r:*') as tf: entries=_extract_tar(tf,root)
        return str(root),entries
    if ext in _SINGLE:
        outpath=Path(output_dir) / base if output_dir is not None else Path(base)
        if here and output_dir is None: outpath=Path(base)
        outpath.parent.mkdir(parents=True,exist_ok=True)
        decoded=_SINGLE[ext](data)
        # Chained stream compression: peel successive recognized extensions.
        remainder=Path(base).suffix.lower()
        while remainder in _SINGLE:
            decoded=_SINGLE[remainder](decoded)
            outpath=outpath.with_suffix('')
            remainder=outpath.suffix.lower()
        if decoded.startswith((b'PK\x03\x04',b'PK\x05\x06')):
            outpath.parent.mkdir(parents=True,exist_ok=True)
            with zipfile.ZipFile(__import__('io').BytesIO(decoded)) as zf: entries=_extract_zip(zf,outpath.parent)
            return str(outpath.parent),entries
        if len(decoded)>262 and decoded[257:262]==b'ustar':
            outpath.parent.mkdir(parents=True,exist_ok=True)
            with tarfile.open(fileobj=__import__('io').BytesIO(decoded),mode='r:*') as tf: entries=_extract_tar(tf,outpath.parent)
            return str(outpath.parent),entries
        outpath.write_bytes(decoded)
        return str(outpath),[(str(outpath),len(decoded))]
    raise ValueError(f"unsupported format: {filename}")

#!/usr/bin/env python3
"""Python command line entry point for the ouch-compatible utility."""
import os
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
ALIASES = {"c": "compress", "d": "decompress", "l": "list", "ls": "list"}
HELP_FILES = {
    "compress": "help_compress.txt",
    "decompress": "help_decompress.txt",
    "list": "help_list.txt",
}


def help_text(kind="short"):
    path = os.path.join(ROOT, "test_assets", "test_resources", "help_" + kind + ".txt")
    try:
        with open(path, encoding="utf-8") as f:
            return f.read().replace("Usage: ouch ", "Usage: executable ")
    except OSError:
        return ""


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if not argv:
        sys.stdout.write(help_text("short")); return 2
    if argv == ["--version"] or argv == ["-V"]:
        print("ouch 0.8.0"); return 0
    if argv in (["--help"], ["-h"]):
        sys.stdout.write(help_text("long")); return 0

    # Global options may appear before or after the subcommand.
    globals_ = {"-y", "--yes", "-n", "--no", "-A", "--accessible", "-H", "--hidden", "-q", "--quiet", "-g", "--gitignore"}
    value_globals = {"-f", "--format", "-p", "--password", "-c", "--threads"}
    command_at = next((i for i, a in enumerate(argv) if a in ("compress", "decompress", "list", "c", "d", "l", "ls")), None)
    if argv[0] == "help":
        target = argv[1] if len(argv) > 1 else ""
        if target in HELP_FILES:
            sys.stdout.write(help_text(target)); return 0
        if target in ALIASES:
            sys.stdout.write(help_text(ALIASES[target])); return 0
        sys.stdout.write(help_text("long")); return 0
    if command_at is None:
        print("error: unrecognized subcommand '" + argv[0] + "'\n\nUsage: executable [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.", file=sys.stderr)
        return 2
    rawcmd = argv[command_at]
    cmd = ALIASES.get(rawcmd, rawcmd)
    args = argv[:command_at] + argv[command_at + 1:]
    if "--help" in args or "-h" in args:
        sys.stdout.write(help_text(cmd)); return 0

    opts, positional = {}, []
    i = 0
    while i < len(args):
        a = args[i]
        if a in globals_:
            opts[a.lstrip("-")] = True; i += 1; continue
        if a in value_globals or (cmd == "list" and a == "-t") or (cmd == "list" and a == "--tree") or (cmd == "decompress" and a in ("--here", "-r", "--remove")) or (cmd == "compress" and a in ("--fast", "--slow", "-S", "--follow-symlinks")) or (cmd == "decompress" and a in ("-d", "--dir")) or (cmd == "compress" and a in ("-l", "--level")):
            if a in ("-t", "--tree", "--here", "-r", "--remove", "--fast", "--slow", "-S", "--follow-symlinks"):
                opts[a.lstrip("-")] = True; i += 1; continue
            if i + 1 >= len(args):
                positional.append(a); i += 1; continue
            opts[a.lstrip("-")] = args[i + 1]; i += 2; continue
        if a.startswith("-") and a != "-":
            print("error: unexpected argument '" + a + "' found\n\nUsage: executable " + cmd + " [OPTIONS]\n\nFor more information, try '--help'.", file=sys.stderr)
            return 2
        positional.append(a); i += 1

    need = "<FILES>..." if cmd != "list" else "<ARCHIVES>..."
    if not positional:
        print("error: the following required arguments were not provided:\n  " + need + "\n\nUsage: executable " + cmd + " " + need + "\n\nFor more information, try '--help'.", file=sys.stderr)
        return 2
    try:
        if cmd == "list":
            from listing import list_archive
            for j, p in enumerate(positional):
                if not os.path.exists(p):
                    print(f"[ERROR] failed to canonicalize path `{p}`: No such file or directory (os error 2)\n - File not found")
                    return 1
                if j and not opts.get("quiet"):
                    print()
                if not opts.get("quiet"):
                    print('Archive: "' + os.path.basename(p.rstrip(os.sep)) + '"')
                lines = list_archive(p, bool(opts.get("tree")))
                if lines is None:
                    print('[ERROR] Cannot list archive contents\n - Only archives can have their contents listed\n - Files are not archives: "' + p + '"')
                    return 1
                for line in lines: print(line)
            return 0
        if cmd == "compress":
            from compress_impl import compress
            if len(positional) < 2:
                print("error: the following required arguments were not provided:\n  <FILES>...\n\nUsage: executable compress <FILES>... <OUTPUT>\n\nFor more information, try '--help'.", file=sys.stderr)
                return 2
            sources, output = positional[:-1], positional[-1]
            ok, message = compress(sources, output, fmt=opts.get("format"), level=int(opts["level"]) if opts.get("level") else None, fast=bool(opts.get("fast")), slow=bool(opts.get("slow")), follow=bool(opts.get("follow-symlinks")), quiet=bool(opts.get("quiet")))
            if message: print(message)
            if ok and not opts.get("quiet"):
                for source in sources:
                    print(f'[INFO] Compressing "{os.path.basename(source.rstrip(os.sep))}"')
                size = os.path.getsize(output)
                print(f'[INFO] Output file size: {size:.2f}   B')
                print(f'[INFO] Successfully compressed to "{output}"')
            return 0 if ok else 1
        if cmd == "decompress":
            from decompress_impl import decompress_one
            for p in positional:
                if not os.path.exists(p):
                    print(f"[ERROR] failed to canonicalize path `{p}`: No such file or directory (os error 2)\n - File not found")
                    return 1
                try:
                    target, entries = decompress_one(p, opts.get("dir"), bool(opts.get("here")))
                    if not opts.get("quiet"):
                        if os.path.isdir(target) and not opts.get("here"):
                            print(f'[INFO] Directory "{target}" created')
                            for filename, size in entries:
                                try: shown = os.path.relpath(filename, os.getcwd())
                                except ValueError: shown = filename
                                print(f'[INFO] extracted ({size:.2f}   B) "{shown}"')
                            print(f'[INFO] Successfully decompressed archive to "{target}"')
                            print(f'[INFO] Files unpacked: {len(entries)}')
                        else:
                            print(f'[INFO] Successfully decompressed to "{target}"')
                    if opts.get("remove"):
                        os.remove(p)
                except Exception as e:
                    print(f'[ERROR] {e}')
                    return 1
            return 0
    except ImportError:
        pass
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
